#!/bin/bash
# Release assets are generated by tools/build-bootstrap-release.py.
set -euo pipefail
umask 077

version='@CCHOUSE_VERSION@'
source_sha='@CCHOUSE_SHA256@'
python_asset='cpython-3.12.16%2B20261124-aarch64-apple-darwin-install_only_stripped.tar.gz'
python_url="https://github.com/astral-sh/python-build-standalone/releases/download/20261124/$python_asset"
python_sha='9d6d9d0d85feda3f9cb4eb3e048f0fed21ed280feda087927eaa4fbc7124826f'
tart_url='https://github.com/openai/tart/releases/download/2.42.0/tart.tar.gz'
tart_sha='a95dda214b5f676298430d665a8174992e6b300dd20c653385b60481ae819ddf'

stage=''
lock=''
bootstrap_to_remove=''
if [ "${1:-}" = "--cleanup-bootstrap" ]; then
  case "${0##*/}" in
    cchouse-bootstrap.*) bootstrap_to_remove="$0" ;;
  esac
fi
cleanup() {
  if [ -n "$stage" ]; then rm -rf -- "$stage"; fi
  if [ -n "$lock" ]; then rmdir -- "$lock"; fi
  if [ -n "$bootstrap_to_remove" ]; then rm -f -- "$bootstrap_to_remove"; fi
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

if [ "$(uname -s)" != Darwin ] || [ "$(sysctl -n hw.optional.arm64 2>/dev/null || true)" != 1 ]; then
  echo '此安装入口需要 Apple Silicon Mac。' >&2
  exit 1
fi
if [[ ! "$source_sha" =~ ^[0-9a-f]{64}$ ]]; then
  echo '请使用 GitHub Release 上已固定版本和 SHA-256 的引导脚本。' >&2
  exit 1
fi

root="$HOME/Library/Application Support/cchouse/bootstrap"
python_home="$root/tools/python-3.12.16-20261124"
tart_home="$root/tools/tart-2.42.0"
code="$root/packages/$version-${source_sha:0:12}"
echo "cchouse $version 将校验并准备私有 Python 和源码，写入 ${root}。"
if command -v tart >/dev/null && tart --version >/dev/null 2>&1; then
  echo '将复用本机 Tart。'
  needs_tart=0
else
  echo '将从官方 Release 校验并准备私有 Tart。'
  needs_tart=1
fi
echo '随后启动 cchouse up，按提示输入节点链接。'

mkdir -p "$root/downloads" "$root/tools" "$root/packages"
if ! mkdir "$root/.prepare"; then
  echo '另一个 cchouse 引导正在准备文件。若上次被强制结束，确认没有引导在运行后删除 bootstrap/.prepare 再试。' >&2
  exit 1
fi
lock="$root/.prepare"
stage="$(mktemp -d "$root/.install.XXXXXXXX")"

verified() {
  [ -f "$1" ] && printf '%s  %s\n' "$2" "$1" | shasum -a 256 -c - >/dev/null
}

fetch() {
  local url="$1" sha="$2" dest="$3"
  if verified "$dest" "$sha"; then return; fi
  echo "下载 ${url##*/}..."
  curl -fsSL --proto '=https' --proto-redir '=https' --retry 2 "$url" -o "$stage/download"
  if ! verified "$stage/download" "$sha"; then
    echo "SHA-256 校验失败：${url##*/}" >&2
    exit 1
  fi
  mv -f -- "$stage/download" "$dest"
}

install_tar() {
  local artifact="$1" dest="$2" member="$3"
  if [ -d "$dest" ]; then return; fi
  mkdir "$stage/tar"
  tar -xzf "$artifact" -C "$stage/tar"
  mv -- "$stage/tar/$member" "$dest"
  rm -rf -- "$stage/tar"
}

source_zip="$root/downloads/cchouse-$version-$source_sha.zip"
fetch "https://github.com/nana-fox/cchouse/releases/download/$version/cchouse-$version.zip" "$source_sha" "$source_zip"
python_tar="$root/downloads/python-$python_sha.tar.gz"
fetch "$python_url" "$python_sha" "$python_tar"
install_tar "$python_tar" "$python_home" python

if [ "$needs_tart" = 1 ]; then
  tart_tar="$root/downloads/tart-$tart_sha.tar.gz"
  fetch "$tart_url" "$tart_sha" "$tart_tar"
  install_tar "$tart_tar" "$tart_home" tart.app
  export PATH="$tart_home/Contents/MacOS:$PATH"
  tart --version >/dev/null
fi
if [ ! -d "$code" ]; then
  mkdir "$stage/zip"
  /usr/bin/ditto -x -k "$source_zip" "$stage/zip"
  test -f "$stage/zip/cchouse/scripts/cchouse.py"
  mv -- "$stage/zip/cchouse" "$code"
fi
rmdir -- "$lock"
lock=''

export PATH="$python_home/bin:$PATH"
export PYTHONUTF8=1
cd "$code"
echo "正在启动 cchouse up。重跑同一条首页命令可续跑。工作目录：$code"
"$python_home/bin/python3" -I scripts/cchouse.py up --tag cc01
